public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email', description='Finds the earliest-created contact for each email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>();
        for (Request request : requests) {
            String email = null;
            if (request != null) {
                email = request.email;
            }
            normalizedEmails.add(normalizeEmail(email));
            results.add(new Result());
        }

        Set<String> uniqueEmails = new Set<String>();
        List<String> emailsToQuery = new List<String>();
        for (String normalizedEmail : normalizedEmails) {
            if (normalizedEmail != null && !uniqueEmails.contains(normalizedEmail)) {
                uniqueEmails.add(normalizedEmail);
                emailsToQuery.add(normalizedEmail);
            }
        }

        Map<String, Contact> earliestContactByEmail = new Map<String, Contact>();
        if (!emailsToQuery.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate 
                FROM Contact 
                WHERE LOWER(Email) IN :emailsToQuery 
                ORDER BY CreatedDate ASC, Id ASC
            ];
            for (Contact contact : contacts) {
                String contactEmail = normalizeEmail(contact.Email);
                if (contactEmail == null) {
                    continue;
                }
                if (!earliestContactByEmail.containsKey(contactEmail)) {
                    earliestContactByEmail.put(contactEmail, contact);
                }
            }
        }

        for (Integer i = 0; i < requests.size(); i++) {
            String normalizedEmail = normalizedEmails.get(i);
            if (normalizedEmail != null) {
                Contact contact = earliestContactByEmail.get(normalizedEmail);
                if (contact != null) {
                    results.get(i).contactId = contact.Id;
                    results.get(i).found = true;
                }
            }
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (trimmed == '') {
            return null;
        }
        return trimmed.toLowerCase();
    }

    public class Request {
        @InvocableVariable(label='Email', required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }
}
