public with sharing class LeadImportService {
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        LeadImportService.ImportResult result = new LeadImportService.ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> candidates = new List<Lead>();
        List<Integer> candidateInputIndices = new List<Integer>();
        Map<String, Integer> firstSeenByEmail = new Map<String, Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads.get(i);

            if (lead == null) {
                continue;
            }

            if (lead.LeadSource == null || lead.LeadSource.trim() == '') {
                lead.LeadSource = 'Web';
            }

            String normalizedEmail = normalizeEmail(lead.Email);

            if (normalizedEmail != null) {
                if (firstSeenByEmail.containsKey(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                firstSeenByEmail.put(normalizedEmail, i);
            }

            candidates.add(lead);
            candidateInputIndices.add(i);
        }

        if (candidates.isEmpty()) {
            return result;
        }

        List<Database.SaveResult> saveResults = Database.insert(candidates, false);

        for (Integer i = 0; i < candidateInputIndices.size(); i++) {
            Integer inputIndex = candidateInputIndices.get(i);
            Database.SaveResult saveResult = saveResults.get(i);

            if (saveResult.isSuccess()) {
                result.successCount++;
                result.insertedIds.add(saveResult.getId());
            } else {
                List<String> errorMessages = new List<String>();

                if (saveResult.getErrors() != null) {
                    for (Database.Error error : saveResult.getErrors()) {
                        String message = error.getMessage();
                        if (message != null) {
                            errorMessages.add(message);
                        }
                    }
                }

                result.errorsByIndex.put(inputIndex, String.join(errorMessages, '; '));
            }
        }

        return result;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }

        String trimmed = email.trim();
        if (trimmed == '') {
            return null;
        }

        return trimmed.toLowerCase();
    }
}
