public class PicklistService {
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (objectApiName == null || objectApiName.trim().length() == 0 ||
                fieldApiName == null || fieldApiName.trim().length() == 0) {
                throw new PicklistServiceException('Object and field API names must not be null or blank.');
            }

            String normalizedObjectApiName = objectApiName.trim();
            String normalizedFieldApiName = fieldApiName.trim();

            Map<String, Schema.SObjectType> globalObjects = Schema.getGlobalDescribe();
            Schema.SObjectType objectType = findObjectType(globalObjects, normalizedObjectApiName);
            if (objectType == null) {
                throw new PicklistServiceException('Object ' + normalizedObjectApiName + ' does not exist.');
            }

            Map<String, Schema.DescribeFieldResult> fields = objectType.getDescribe().fields;
            Schema.DescribeFieldResult fieldDescribe = findField(fields, normalizedFieldApiName);
            if (fieldDescribe == null) {
                throw new PicklistServiceException(
                    'Field ' + normalizedFieldApiName + ' does not exist on object ' + normalizedObjectApiName + '.'
                );
            }

            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTISELECTPICKLIST) {
                throw new PicklistServiceException(
                    'Field ' + normalizedFieldApiName + ' is not a picklist or multi-select picklist.'
                );
            }

            List<Schema.PicklistEntry> picklistValues = fieldDescribe.getPicklistValues();
            if (picklistValues == null) {
                picklistValues = new List<Schema.PicklistEntry>();
            }

            List<Schema.PicklistEntry> defaultValues = fieldDescribe.getPicklistValuesByDefault();
            Set<String> defaultValueSet = new Set<String>();
            if (defaultValues != null) {
                for (Schema.PicklistEntry defaultValue : defaultValues) {
                    if (defaultValue != null && defaultValue.getValue() != null) {
                        defaultValueSet.add(defaultValue.getValue());
                    }
                }
            }

            List<Option> options = new List<Option>();
            for (Schema.PicklistEntry picklistEntry : picklistValues) {
                if (picklistEntry == null) {
                    continue;
                }

                Boolean active = picklistEntry.getIsActive();
                if (active == null || active != true) {
                    continue;
                }

                String value = picklistEntry.getValue();
                if (value == null) {
                    continue;
                }

                options.add(new Option(value, picklistEntry.getLabel(), defaultValueSet.contains(value)));
            }

            return options;
        } catch (PicklistServiceException pse) {
            throw pse;
        } catch (Exception e) {
            throw new PicklistServiceException('Unable to retrieve active picklist values: ' + String.valueOf(e.getMessage()));
        }
    }

    private static Schema.SObjectType findObjectType(
        Map<String, Schema.SObjectType> globalObjects,
        String objectApiName
    ) {
        if (globalObjects == null) {
            return null;
        }

        for (String key : globalObjects.keySet()) {
            if (key != null && key.equalsIgnoreCase(objectApiName)) {
                return globalObjects.get(key);
            }
        }

        return null;
    }

    private static Schema.DescribeFieldResult findField(
        Map<String, Schema.DescribeFieldResult> fields,
        String fieldApiName
    ) {
        if (fields == null) {
            return null;
        }

        for (String key : fields.keySet()) {
            if (key != null && key.equalsIgnoreCase(fieldApiName)) {
                return fields.get(key);
            }
        }

        return null;
    }
}
