public class OpportunityPipelineHandler {
    private static Boolean inHandler = false;

    public static void process() {
        if (inHandler) {
            return;
        }

        inHandler = true;
        try {
            Set<Id> affectedAccounts = new Set<Id>();

            if (Trigger.old != null) {
                for (SObject s : Trigger.old) {
                    Opportunity o = (Opportunity) s;
                    if (o.AccountId != null) {
                        affectedAccounts.add(o.AccountId);
                    }
                }
            }

            if (Trigger.new != null) {
                for (SObject s : Trigger.new) {
                    Opportunity o = (Opportunity) s;
                    if (o.AccountId != null) {
                        affectedAccounts.add(o.AccountId);
                    }
                }
            }

            if (affectedAccounts.isEmpty()) {
                return;
            }

            Map<Id, Currency> pipelineByAccount = new Map<Id, Currency>();
            Map<Id, Integer> countByAccount = new Map<Id, Integer>();

            List<Opportunity> openOpps = [
                SELECT AccountId, Amount
                FROM Opportunity
                WHERE AccountId IN :affectedAccounts AND IsClosed = false
            ];

            Currency zero = (Currency) 0;

            for (Opportunity o : openOpps) {
                if (o.AccountId == null) {
                    continue;
                }

                Currency amount = (o.Amount == null) ? zero : o.Amount;
                Currency currentTotal = pipelineByAccount.get(o.AccountId);
                pipelineByAccount.put(o.AccountId, (currentTotal == null ? zero : currentTotal) + amount);

                Integer currentCount = countByAccount.get(o.AccountId);
                countByAccount.put(o.AccountId, (currentCount == null ? 0 : currentCount) + 1);
            }

            Map<Id, Account> accountMap = new Map<Id, Account>([
                SELECT Id, FB_Open_Pipeline__c, FB_Open_Oppportunities__c
                FROM Account
                WHERE Id IN :affectedAccounts
            ]);

            List<Account> accountsToUpdate = new List<Account>();

            for (Id accountId : affectedAccounts) {
                Account acc = accountMap.get(accountId);
                if (acc == null) {
                    continue;
                }

                Currency newPipeline = pipelineByAccount.get(accountId);
                if (newPipeline == null) {
                    newPipeline = zero;
                }

                Integer newCount = countByAccount.get(accountId);
                if (newCount == null) {
                    newCount = 0;
                }

                Boolean pipelineChanged =
                    acc.FB_Open_Pipeline__c == null || acc.FB_Open_Pipeline__c != newPipeline;

                Boolean countChanged =
                    acc.FB_Open_Oppportunities__c == null || acc.FB_Open_Oppportunities__c != newCount;

                if (pipelineChanged || countChanged) {
                    acc.FB_Open_Pipeline__c = newPipeline;
                    acc.FB_Open_Oppportunities__c = newCount;
                    accountsToUpdate.add(acc);
                }
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }
        } finally {
            inHandler = false;
        }
    }
}
```

The key fix: `QueryLocator` is a nested type of `Database` (as used in the `Database.BatchableSObject` interface), so the correct qualified name is `Database.QueryLocator` — not `System.QueryLocator` and not bare `QueryLocator`. That invalid-type error was also cascading and breaking the `LogPurgeJob.class` literal, which is why `System.schedule(...)` was being reported as a bad signature. I also changed the DML to delete an `SObject` list (`List<Id>` is not a valid DML target) and dropped the redundant `(Id)` cast since `System.schedule` already returns `Id`.

