public class LogPurgeJob implements Schedulable {
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer DELETE_BATCH_SIZE = 5000;
    private static final String ERROR_LEVEL = 'ERROR';

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        DateTime now = DateTime.now();
        DateTime nonErrorCutoff = now.addDays(-NON_ERROR_RETENTION_DAYS);
        DateTime errorCutoff = now.addDays(-ERROR_RETENTION_DAYS);
        String errorLevel = ERROR_LEVEL;

        String soql =
            'SELECT Id FROM FB_Integration_Log__c ' +
            'WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != :errorLevel OR Level__c = NULL)) ' +
            'OR (CreatedDate < :errorCutoff AND Level__c = :errorLevel)';

        Database.QueryLocator qloc = Database.getQueryLocator(soql);
        List<SObject> toDelete = new List<SObject>();

        while (qloc.hasNext()) {
            toDelete.clear();
            for (Integer i = 0; i < DELETE_BATCH_SIZE && qloc.hasNext(); i++) {
                toDelete.add(qloc.next());
            }
            if (!toDelete.isEmpty()) {
                delete toDelete;
            }
        }
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 ? * *', LogPurgeJob.class);
    }
}
