public inherited sharing class AccountsSelector extends fflib_SObjectSelector {
    private static final Integer ID_CHUNK_SIZE = 1000;

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fieldList = new List<Schema.SObjectField>();
        Set<String> fieldNames = new Set<String>();

        addUniqueField(fieldList, fieldNames, Account.Id);
        addUniqueField(fieldList, fieldNames, Account.Name);
        addUniqueField(fieldList, fieldNames, Account.Industry);

        Schema.FieldSet creditReviewFieldSet = $ObjectType.Account.FieldSets.get('Credit_Review');
        if (creditReviewFieldSet != null) {
            for (Schema.FieldSetMember fieldSetMember : creditReviewFieldSet.getFields()) {
                addUniqueField(fieldList, fieldNames, fieldSetMember.getSObjectField());
            }
        }

        return fieldList;
    }

    public virtual String getDataAccessMode() {
        return 'USER_MODE';
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return queryAccounts(accountIds, false);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        return queryAccounts(accountIds, true);
    }

    private List<Account> queryAccounts(Set<Id> accountIds, Boolean withContacts) {
        List<Account> accounts = new List<Account>();

        if (accountIds == null || accountIds.isEmpty()) {
            return accounts;
        }

        List<Id> idsToQuery = new List<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                idsToQuery.add(accountId);
            }
        }

        if (idsToQuery.isEmpty()) {
            return accounts;
        }

        Integer totalIds = idsToQuery.size();

        for (Integer offset = 0; offset < totalIds; offset += ID_CHUNK_SIZE) {
            Integer end = Math.min(offset + ID_CHUNK_SIZE, totalIds);
            List<Id> idChunk = idsToQuery.subList(offset, end);
            String query = buildAccountQuery(idChunk, withContacts);
            accounts.addAll((List<Account>) Database.query(query));
        }

        return accounts;
    }

    private String buildAccountQuery(List<Id> accountIds, Boolean withContacts) {
        String accountFields = buildFieldList(getSObjectFieldList());
        String query = 'SELECT ' + accountFields + ' FROM Account WHERE Id IN :accountIds';

        if (withContacts) {
            List<Schema.SObjectField> contactFields = new ContactsSelector().getSObjectFieldList();
            if (contactFields != null && !contactFields.isEmpty()) {
                query += ' ' + buildChildFieldList('Contacts', contactFields);
            }
        }

        String dataAccessMode = getDataAccessMode();
        if (dataAccessMode == null || dataAccessMode.isEmpty()) {
            dataAccessMode = 'USER_MODE';
        }
        query += ' WITH ' + dataAccessMode;

        return query;
    }

    private String buildFieldList(List<Schema.SObjectField> fields) {
        if (fields == null || fields.isEmpty()) {
            return 'Id';
        }

        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : fields) {
            if (field != null) {
                fieldNames.add(field.getDescribe().getName());
            }
        }

        if (fieldNames.isEmpty()) {
            return 'Id';
        }

        return String.join(fieldNames, ', ');
    }

    private String buildChildFieldList(String relationshipName, List<Schema.SObjectField> fields) {
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : fields) {
            if (field != null) {
                fieldNames.add(relationshipName + '.' + field.getDescribe().getName());
            }
        }

        return String.join(fieldNames, ', ');
    }

    private void addUniqueField(
        List<Schema.SObjectField> fieldList,
        Set<String> fieldNames,
        Schema.SObjectField field
    ) {
        if (field == null) {
            return;
        }

        String fieldName = field.getDescribe().getName();
        if (!fieldNames.contains(fieldName)) {
            fieldNames.add(fieldName);
            fieldList.add(field);
        }
    }
}
