trigger OpportunityTrigger on Opportunity (after insert, after update, after delete) {
    // Different from one future call per opportunity: collect the affected
    // accounts and queue them in chunks. One future call per opportunity can
    // exceed the 50 @future calls-per-transaction limit for CPQ batches of 200.
    Set<Id> affectedAccountIds = new Set<Id>();

    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                affectedAccountIds.add(opp.AccountId);
            }
        }
    }

    if (Trigger.isUpdate) {
        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Opportunity newOpp = Trigger.new[i];
            Opportunity oldOpp = Trigger.old[i];

            if (newOpp.AccountId != oldOpp.AccountId) {
                if (oldOpp.AccountId != null) {
                    affectedAccountIds.add(oldOpp.AccountId);
                }
                if (newOpp.AccountId != null) {
                    affectedAccountIds.add(newOpp.AccountId);
                }
            } else if (newOpp.StageName != oldOpp.StageName || newOpp.Amount != oldOpp.Amount) {
                if (newOpp.AccountId != null) {
                    affectedAccountIds.add(newOpp.AccountId);
                }
            }
        }
    }

    if (Trigger.isDelete) {
        for (Opportunity opp : Trigger.old) {
            if (opp.AccountId != null && opp.IsClosed == false) {
                affectedAccountIds.add(opp.AccountId);
            }
        }
    }

    if (!affectedAccountIds.isEmpty()) {
        List<Id> accountIds = new List<Id>(affectedAccountIds);
        Integer chunkSize = 5000;

        for (Integer startIndex = 0; startIndex < accountIds.size(); startIndex += chunkSize) {
            Integer stopIndex = startIndex + chunkSize;
            if (stopIndex > accountIds.size()) {
                stopIndex = accountIds.size();
            }

            List<String> idStrings = new List<String>();
            for (Integer i = startIndex; i < stopIndex; i++) {
                idStrings.add(String.valueOf(accountIds[i]));
            }

            AccountRatingService.recalculate(String.join(idStrings, ','));
        }
    }
}
