public with sharing class AccountRatingService {
    private static final Integer ACCOUNT_CHUNK_SIZE = 1000;

    @future
    public static void recalculate(String accountIdsCsv) {
        if (accountIdsCsv == null || accountIdsCsv.length() == 0) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        for (String accountId : accountIdsCsv.split(',')) {
            if (accountId.length() > 0) {
                accountIds.add((Id) accountId);
            }
        }

        recalculateAccounts(accountIds);
    }

    private static void recalculateAccounts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> ids = new List<Id>(accountIds);
        List<Account> accountsToUpdate = new List<Account>();
        Map<Id, Account> accountsToUpdateMap = new Map<Id, Account>();

        for (Integer startIndex = 0; startIndex < ids.size(); startIndex += ACCOUNT_CHUNK_SIZE) {
            Integer stopIndex = startIndex + ACCOUNT_CHUNK_SIZE;
            if (stopIndex > ids.size()) {
                stopIndex = ids.size();
            }

            List<Id> chunk = new List<Id>();
            for (Integer i = startIndex; i < stopIndex; i++) {
                chunk.add(ids[i]);
            }

            Map<Id, AggregateResult> openOppByAccount = new Map<Id, AggregateResult>();
            for (AggregateResult result : [
                SELECT AccountId, COUNT(Id) openCount
                FROM Opportunity
                WHERE AccountId IN :chunk
                AND IsClosed = false
                GROUP BY AccountId
            ]) {
                openOppByAccount.put((Id) result.get('AccountId'), result);
            }

            Map<Id, AggregateResult> hotOppByAccount = new Map<Id, AggregateResult>();
            for (AggregateResult result : [
                SELECT AccountId, COUNT(Id) hotCount
                FROM Opportunity
                WHERE AccountId IN :chunk
                AND IsClosed = false
                AND Amount >= 100000
                GROUP BY AccountId
            ]) {
                hotOppByAccount.put((Id) result.get('AccountId'), result);
            }

            Map<Id, Account> accountsById = new Map<Id, Account>([
                SELECT Id, Rating
                FROM Account
                WHERE Id IN :chunk
            ]);

            for (Id accountId : chunk) {
                Account account = accountsById.get(accountId);
                if (account == null) {
                    continue;
                }

                String rating;
                if (hotOppByAccount.containsKey(accountId)) {
                    rating = 'Hot';
                } else if (openOppByAccount.containsKey(accountId)) {
                    rating = 'Warm';
                } else {
                    rating = 'Cold';
                }

                if (account.Rating != rating && !accountsToUpdateMap.containsKey(accountId)) {
                    account.Rating = rating;
                    accountsToUpdateMap.put(accountId, account);
                    accountsToUpdate.add(account);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
