public class RenewalReminderService {
    // Passing 200 opportunities in one transaction is a bad idea: Apex can send only
    // 100 emails per transaction. This method stops gracefully if that limit is reached
    // and returns the number of emails actually sent.

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.size() == 0) {
            return 0;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.size() == 0) {
            return 0;
        }

        List<Id> uniqueIdList = new List<Id>();
        for (Id opportunityId : uniqueOpportunityIds) {
            uniqueIdList.add(opportunityId);
        }

        List<Opportunity> opportunities = [
            SELECT Id,
                   Name,
                   CloseDate,
                   OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueIdList
        ];

        Integer sentCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (opportunity.OwnerId == null) {
                continue;
            }

            try {
                Messaging.SingleEmailMessage message = new Messaging.SingleEmailMessage();
                message.setTargetObjectId(opportunity.OwnerId);
                message.setSaveAsActivity(false);

                String opportunityName = opportunity.Name == null ? '' : opportunity.Name;
                message.setSubject('Renewal due: ' + opportunityName);

                String closeDateText = 'not set';
                if (opportunity.CloseDate != null) {
                    closeDateText = String.valueOf(opportunity.CloseDate) + ' ' + opportunity.CloseDate.format();
                }
                message.setPlainTextBody('Close date: ' + closeDateText + '.');

                List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
                messages.add(message);
                Messaging.SendEmailResult[] results = Messaging.sendEmail(messages);

                if (results != null && results.size() > 0 && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (LimitException e) {
                break;
            } catch (Exception e) {
                // A single failed email should not prevent the remaining reminders.
            }
        }

        return sentCount;
    }
}
