import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId = '';

    casesUrl = '';

    connectedCallback() {
        this.generateCaseListUrl();
    }

    handleAction(event) {
        const source = event.currentTarget || event.target;
        const action = source && source.dataset ? source.dataset.action : undefined;

        if (action === 'new-contact') {
            this.openNewContact();
        } else if (action === 'contacts') {
            this.openContacts();
        } else if (action === 'edit') {
            this.openEdit();
        }
    }

    openNewContact() {
        if (!this.recordId) {
            return;
        }

        this.runNavigate({
            type: 'standard__objectPage',
            attributes: {
                apiName: 'Contact',
                actionName: 'new'
            },
            state: {
                defaultFieldValues: encodeDefaultFieldValues({
                    AccountId: this.recordId
                })
            }
        });
    }

    openContacts() {
        if (!this.recordId) {
            return;
        }

        this.runNavigate({
            type: 'standard__relatedList',
            attributes: {
                objectApiName: 'Account',
                recordId: this.recordId,
                relatedListApiName: 'Contacts'
            }
        });
    }

    openEdit() {
        if (!this.recordId) {
            return;
        }

        this.runNavigate({
            type: 'standard__recordPage',
            attributes: {
                apiName: 'Account',
                recordId: this.recordId,
                actionName: 'edit'
            }
        });
    }

    generateCaseListUrl() {
        this.runGenerateUrl({
            type: 'standard__objectPage',
            attributes: {
                apiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        })
            .then((generated) => {
                if (typeof generated === 'string') {
                    this.casesUrl = generated;
                } else if (generated && typeof generated === 'object') {
                    this.casesUrl = generated.url || generated.type;
                }
            })
            .catch((error) => {
                console.error('Failed to generate Case list URL', error);
            });
    }

    runNavigate(pageRef) {
        const navigate = this.getNavigationMethod('Navigate');
        if (typeof navigate !== 'function') {
            return Promise.reject(new Error('NavigationMixin.Navigate is not available.'));
        }

        return Promise.resolve(navigate.call(this, pageRef));
    }

    runGenerateUrl(config) {
        const generateUrl = this.getNavigationMethod('GenerateUrl');
        if (typeof generateUrl !== 'function') {
            return Promise.reject(new Error('NavigationMixin.GenerateUrl is not available.'));
        }

        return Promise.resolve(generateUrl.call(this, config));
    }

    getNavigationMethod(methodName) {
        const key = NavigationMixin[methodName];

        if (key !== undefined && key !== null) {
            const instanceMethod = this[key];
            if (typeof instanceMethod === 'function') {
                return instanceMethod;
            }
        }

        if (typeof key === 'function') {
            return key;
        }

        return undefined;
    }
}
