import { LightningElement } from 'lwc';
import { searchContacts } from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    results = [];
    error = undefined;

    _timer;
    _requestId = 0;
    _disconnected = false;

    connectedCallback() {
        this._disconnected = false;
    }

    disconnectedCallback() {
        this._disconnected = true;
        clearTimeout(this._timer);
        this._timer = undefined;
        this._requestId += 1;
    }

    handleChange(event) {
        clearTimeout(this._timer);
        this._timer = undefined;
        this._requestId += 1;

        const detailValue = event.detail ? event.detail.value : undefined;
        const rawValue = detailValue !== undefined
            ? detailValue
            : (event.target ? event.target.value : '');
        const value = String(rawValue || '').trim();

        if (value.length < 2) {
            this.error = undefined;
            this.results = [];
            return;
        }

        this._timer = setTimeout(() => {
            this._timer = undefined;
            this.runSearch(value);
        }, 300);
    }

    runSearch(searchTerm) {
        if (this._disconnected) {
            return;
        }

        const trimmed = String(searchTerm || '').trim();

        if (trimmed.length < 2) {
            this.error = undefined;
            this.results = [];
            return;
        }

        this._requestId += 1;
        const requestId = this._requestId;
        this.error = undefined;

        searchContacts({ searchTerm: trimmed })
            .then((contacts) => {
                if (this._disconnected || requestId !== this._requestId) {
                    return;
                }

                this.results = Array.isArray(contacts) ? contacts : [];
                this.error = undefined;
            })
            .catch((error) => {
                if (this._disconnected || requestId !== this._requestId) {
                    return;
                }

                this.error = error && error.body ? error.body.message : undefined;
                this.results = [];
            });
    }
}
