    handleReset() {
        this.getEditors().forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = this.getEditors();
        let allValid = true;

        editors.forEach((editor) => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        const resultLines = editors.map((editor) => editor.getValue());

        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines: resultLines },
                bubbles: true,
                composed: true
            })
        );
    }
