import { LightningElement } from 'lwc';
import { getQueueStats } from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60 * 1000;

export default class QueueMonitor extends LightningElement {
    waiting = undefined;
    longestWaitMinutes = undefined;
    error = undefined;

    hasStats = false;
    hasstats = false;
    hasError = false;
    haserror = false;

    _isConnected = false;
    _pageVisible = false;
    _isFetching = false;
    _pollingInterval = undefined;
    _visibilityListener = undefined;
    _requestId = 0;

    connectedCallback() {
        this._isConnected = true;
        this._pageVisible = this._isVisible();
        this._resetState();

        if (this._visibilityListener) {
            document.removeEventListener('visibilitychange', this._visibilityListener);
        }

        this._visibilityListener = () => this._handleVisibilityChange();
        document.addEventListener('visibilitychange', this._visibilityListener);

        if (this._pageVisible) {
            this._startPolling();
            this._loadStats();
        }
    }

    disconnectedCallback() {
        this._isConnected = false;
        this._removeVisibilityListener();
        this._stopPolling();
        this._requestId += 1;
        this._isFetching = false;
        this._resetState();
    }

    _resetState() {
        this.waiting = undefined;
        this.longestWaitMinutes = undefined;
        this.error = undefined;

        this.hasStats = false;
        this.hasstats = false;
        this.hasError = false;
        this.haserror = false;
    }

    _isVisible() {
        return document.visibilityState !== 'hidden';
    }

    _handleVisibilityChange() {
        if (!this._isConnected) {
            return;
        }

        const nowVisible = this._isVisible();
        if (nowVisible === this._pageVisible) {
            return;
        }

        this._pageVisible = nowVisible;

        if (nowVisible) {
            this._startPolling();
            this._loadStats();
        } else {
            this._stopPolling();
        }
    }

    _startPolling() {
        this._stopPolling();

        if (!this._isConnected || !this._isVisible()) {
            return;
        }

        this._pollingInterval = setInterval(() => {
            if (this._isConnected && this._isVisible()) {
                this._loadStats();
            }
        }, REFRESH_INTERVAL_MS);
    }

    _stopPolling() {
        if (this._pollingInterval) {
            clearInterval(this._pollingInterval);
            this._pollingInterval = undefined;
        }
    }

    _removeVisibilityListener() {
        if (this._visibilityListener) {
            document.removeEventListener('visibilitychange', this._visibilityListener);
            this._visibilityListener = undefined;
        }
    }

    async _loadStats() {
        if (!this._isConnected || this._isFetching) {
            return;
        }

        const requestId = this._requestId;
        this._isFetching = true;

        try {
            const stats = await getQueueStats();

            if (this._isConnected && requestId === this._requestId) {
                this.waiting = stats.waiting;
                this.longestWaitMinutes = stats.longestWaitMinutes;

                this.hasStats = true;
                this.hasstats = true;

                this.error = undefined;
                this.hasError = false;
                this.haserror = false;
            }
        } catch (error) {
            if (this._isConnected && requestId === this._requestId) {
                let message;

                if (error && error.body && error.body.message != null) {
                    message = error.body.message;
                } else if (error && error.message) {
                    message = error.message;
                } else {
                    message = 'Error loading queue statistics.';
                }

                this.error = message;
                this.hasError = true;
                this.haserror = true;
            }
        } finally {
            if (requestId === this._requestId) {
                this._isFetching = false;
            }
        }
    }
}
