import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label = '';

    selectedValue = '';
    optionList = [];
    activeIndex = 0;

    @api get value() {
        return this.selectedValue;
    }

    set value(newValue) {
        this.selectedValue = this.normalizeValue(newValue);
        this.syncActiveToSelected();
    }

    @api get options() {
        return this.optionList;
    }

    set options(newValue) {
        this.optionList = Array.isArray(newValue) ? newValue : [];
        this.syncActiveToSelected();
    }

    get ariaLabel() {
        return this.label == null ? '' : String(this.label);
    }

    get activeOptionId() {
        const count = this.optionList.length;
        if (count === 0) {
            return '';
        }

        let index = this.activeIndex;
        if (typeof index !== 'number' || !Number.isInteger(index) || index < 0 || index >= count) {
            index = 0;
        }

        return `option-${index}`;
    }

    get selectedOptionIndex() {
        return this.optionList.findIndex(
            (option) => option != null && this.isSameValue(option.value, this.selectedValue)
        );
    }

    get optionData() {
        const selectedIndex = this.selectedOptionIndex;

        return this.optionList.map((option, index) => {
            const value = option ? this.getDataValue(option.value) : '';
            const label = option ? this.getLabel(option.label) : '';

            return {
                id: `option-${index}`,
                value,
                label,
                selected: index === selectedIndex ? 'true' : 'false'
            };
        });
    }

    normalizeValue(value) {
        return value === null || value === undefined ? '' : value;
    }

    getDataValue(value) {
        return value == null ? '' : String(value);
    }

    getLabel(label) {
        return label == null ? '' : String(label);
    }

    isSameValue(a, b) {
        const normalizedA = a == null ? '' : a;
        const normalizedB = b == null ? '' : b;

        if (normalizedA === normalizedB) {
            return true;
        }

        if (normalizedA == null || normalizedB == null) {
            return false;
        }

        return String(normalizedA) === String(normalizedB);
    }

    syncActiveToSelected() {
        const selectedIndex = this.selectedOptionIndex;
        this.activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    onKeyDown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        const count = this.optionList.length;
        if (count === 0) {
            return;
        }

        let index = this.activeIndex;
        if (typeof index !== 'number' || !Number.isInteger(index) || index < 0 || index >= count) {
            index = 0;
        }

        if (key === 'ArrowDown') {
            if (index < count - 1) {
                this.activeIndex = index + 1;
            }
        } else if (key === 'ArrowUp') {
            if (index > 0) {
                this.activeIndex = index - 1;
            }
        } else if (key === 'Home') {
            this.activeIndex = 0;
        } else if (key === 'End') {
            this.activeIndex = count - 1;
        } else if (key === 'Enter' || key === ' ') {
            this.selectOption(index);
        }
    }

    onOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this.optionList.findIndex(
            (option) => option != null && this.getDataValue(option.value) === clickedValue
        );

        if (index !== -1) {
            this.selectOption(index);
        }
    }

    selectOption(index) {
        const option = this.optionList[index];
        if (!option) {
            return;
        }

        this.activeIndex = index;

        const newValue = this.normalizeValue(option.value);
        if (!this.isSameValue(option.value, this.selectedValue)) {
            this.selectedValue = newValue;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: newValue },
                bubbles: true,
                composed: true
            }));
        }
    }
}
