import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    items = [];
    newLabel = '';
    nextId = 1;

    get tasks() {
        return this.copyTasks(this.items);
    }

    @api set tasks(value) {
        this.items = this.copyTasks(value);
    }

    get headingDisplay() {
        if (this.heading == null) {
            return '';
        }
        return String(this.heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    copyTasks(value) {
        if (!Array.isArray(value)) {
            return [];
        }
        return value.map((task) => (task ? { ...task } : {}));
    }

    handleLabelChange(event) {
        const detail = event && event.detail;
        this.newLabel = detail && detail.value != null ? detail.value : '';
    }

    handleAdd() {
        const input = this.template.querySelector('.new-task');
        const inputValue = input && input.value != null ? input.value : this.newLabel;
        const label = String(inputValue == null ? '' : inputValue).trim();

        if (!label) {
            return;
        }

        this.items = [
            ...this.items,
            {
                id: this.generateId(),
                label: label,
                done: false
            }
        ];

        this.newLabel = '';
        if (input) {
            input.value = '';
        }

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label: label },
                bubbles: true,
                composed: true
            })
        );
    }

    generateId() {
        let id;
        do {
            id = `new-${Date.now()}-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === String(id)));
        return id;
    }

    handleToggle(event) {
        const target = event && event.target;
        const id = target && target.dataset && target.dataset.id;

        if (id === undefined || id === null) {
            return;
        }

        const nextDone = Boolean(target.checked);
        const targetId = String(id);

        this.items = this.items.map((task) =>
            String(task.id) === targetId ? { ...task, done: nextDone } : task
        );
    }
}
