public class HouseholdService {
    private static final String HOUSEHOLD_RT_DEVELOPER_NAME = 'HH_Account';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Create the single NPSP household; NPSP names it automatically,
        // so we intentionally do not set Account.Name.
        Account household = new Account(RecordTypeId = getHouseholdRecordTypeId());
        insert household;

        // Link every member to the newly created household (bulk-safe).
        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        // The first contact in the list is the household's primary contact.
        household.npe01__One2OneContact__c = members.get(0).Id;
        update household;

        return household.Id;
    }

    private static Id getHouseholdRecordTypeId() {
        // Look up the record type by DeveloperName so no record type Id is
        // hard-coded.
        RecordType householdRt = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
            AND DeveloperName = :HOUSEHOLD_RT_DEVELOPER_NAME
            LIMIT 1
        ];
        return householdRt.Id;
    }
}
