public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static final String PAIR_SEPARATOR = '|';

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        List<SoftCreditRequest> candidates = new List<SoftCreditRequest>();
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> pairKeys = new Set<String>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }
            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive number.');
            }
            if (request.opportunityId == null || request.contactId == null) {
                continue;
            }

            String pairKey = buildPairKey(request.opportunityId, request.contactId);
            if (pairKeys.contains(pairKey)) {
                continue;
            }

            pairKeys.add(pairKey);
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
            candidates.add(request);
        }

        if (candidates.isEmpty()) {
            return;
        }

        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>();
        for (Opportunity opportunity : [
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]) {
            opportunities.put(opportunity.Id, opportunity);
        }

        Map<Id, Contact> contacts = new Map<Id, Contact>();
        for (Contact contact : [
            SELECT Id, Name
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            contacts.put(contact.Id, contact);
        }

        Map<String, npsp__Partial_Soft_Credit__c> existingCredits = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c credit : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            existingCredits.put(buildPairKey(credit.npsp__Opportunity__c, credit.npsp__Contact__c), credit);
        }

        Map<String, List<OpportunityContactRole>> contactRoles = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole opportunityContactRole : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ]) {
            String pairKey = buildPairKey(opportunityContactRole.OpportunityId, opportunityContactRole.ContactId);
            if (!contactRoles.containsKey(pairKey)) {
                contactRoles.put(pairKey, new List<OpportunityContactRole>());
            }
            contactRoles.get(pairKey).add(opportunityContactRole);
        }

        List<SoftCreditRequest> validRequests = new List<SoftCreditRequest>();
        for (SoftCreditRequest request : candidates) {
            Opportunity opportunity = opportunities.get(request.opportunityId);
            if (opportunity == null) {
                continue;
            }

            if (opportunity.Amount != null && request.amount > opportunity.Amount) {
                throw new SoftCreditException('Soft credit amount cannot exceed the opportunity amount.');
            }

            if (opportunity.npsp__Primary_Contact__c == request.contactId) {
                throw new SoftCreditException('Cannot create a partial soft credit for the primary contact.');
            }

            Contact contact = contacts.get(request.contactId);
            if (contact == null) {
                continue;
            }

            validRequests.add(request);
        }

        if (validRequests.isEmpty()) {
            return;
        }

        List<OpportunityContactRole> opportunityContactRolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> opportunityContactRolesToUpdate = new List<OpportunityContactRole>();
        List<Id> opportunityContactRoleIdsToDelete = new List<Id>();
        Map<String, OpportunityContactRole> targetRoles = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest request : validRequests) {
            String pairKey = buildPairKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> existingRoles = contactRoles.get(pairKey);
            OpportunityContactRole targetRole;

            if (existingRoles == null || existingRoles.isEmpty()) {
                targetRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
                opportunityContactRolesToInsert.add(targetRole);
            } else {
                targetRole = null;
                for (OpportunityContactRole existingRole : existingRoles) {
                    if (existingRole.Role == request.role) {
                        targetRole = existingRole;
                        break;
                    }
                }

                if (targetRole == null) {
                    targetRole = existingRoles[0];
                    if (targetRole.Role != request.role) {
                        targetRole.Role = request.role;
                        opportunityContactRolesToUpdate.add(targetRole);
                    }
                }

                for (OpportunityContactRole existingRole : existingRoles) {
                    if (existingRole.Id != targetRole.Id) {
                        opportunityContactRoleIdsToDelete.add(existingRole.Id);
                    }
                }
            }

            targetRoles.put(pairKey, targetRole);
        }

        if (!opportunityContactRolesToInsert.isEmpty()) {
            insert opportunityContactRolesToInsert;
        }
        if (!opportunityContactRolesToUpdate.isEmpty()) {
            update opportunityContactRolesToUpdate;
        }
        if (!opportunityContactRoleIdsToDelete.isEmpty()) {
            delete opportunityContactRoleIdsToDelete;
        }

        List<npsp__Partial_Soft_Credit__c> creditsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest request : validRequests) {
            String pairKey = buildPairKey(request.opportunityId, request.contactId);
            OpportunityContactRole targetRole = targetRoles.get(pairKey);
            Contact contact = contacts.get(request.contactId);
            npsp__Partial_Soft_Credit__c credit = existingCredits.get(pairKey);

            if (credit == null) {
                credit = new npsp__Partial_Soft_Credit__c();
            }

            credit.npsp__Opportunity__c = request.opportunityId;
            credit.npsp__Contact__c = request.contactId;
            credit.npsp__Amount__c = request.amount;
            credit.npsp__Role_Name__c = request.role;
            credit.npsp__Contact_Role_ID__c = String.valueOf(targetRole.Id);
            credit.npsp__Contact_Name__c = contact.Name;

            creditsToUpsert.add(credit);
        }

        if (!creditsToUpsert.isEmpty()) {
            upsert creditsToUpsert;
        }
    }

    private static String buildPairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + PAIR_SEPARATOR + String.valueOf(contactId);
    }
}
