public class GiftService {
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact ID is required.');
        }

        Contact contact = [SELECT Id, FirstName, LastName, AccountId FROM Contact WHERE Id = :contactId LIMIT 1];
        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Id householdId = contact.AccountId;
        List<Contact> householdMembers = new List<Contact>();
        if (householdId != null) {
            householdMembers = [SELECT Id FROM Contact WHERE AccountId = :householdId];
        }

        Map<Id, OpportunityContactRole> rolesByContact = new Map<Id, OpportunityContactRole>();
        rolesByContact.put(
            contact.Id,
            new OpportunityContactRole(
                ContactId = contact.Id,
                IsPrimary = true,
                Role = ROLE_DONOR
            )
        );

        for (Contact member : householdMembers) {
            if (member.Id != contact.Id && !rolesByContact.containsKey(member.Id)) {
                rolesByContact.put(
                    member.Id,
                    new OpportunityContactRole(
                        ContactId = member.Id,
                        IsPrimary = false,
                        Role = ROLE_HOUSEHOLD_MEMBER
                    )
                );
            }
        }

        String name = (contact.FirstName == null ? '' : contact.FirstName) + ' ' +
                      (contact.LastName == null ? '' : contact.LastName) +
                      ' Donation ' + giftDate.gmtformat('yyyy-MM-dd');

        Opportunity opportunity = new Opportunity(
            Name = name,
            AccountId = householdId,
            StageName = STAGE_CLOSED_WON,
            IsClosed = true,
            IsWon = true,
            Amount = amount,
            CloseDate = giftDate,
            npsp__Primary_Contact__c = contact.Id
        );
        insert opportunity;

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        for (OpportunityContactRole role : rolesByContact.values()) {
            role.OpportunityId = opportunity.Id;
            rolesToInsert.add(role);
        }
        insert rolesToInsert;

        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opportunity.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        return opportunity.Id;
    }
}
