public with sharing class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Map<String, Id> childByDirectedKey = new Map<String, Id>();
        Map<String, Id> parentByDirectedKey = new Map<String, Id>();
        Map<String, List<String>> directedKeysByUnorderedPair = new Map<String, List<String>>();

        for (Map.Entry<Id, Id> entry : parentIdByChildId.entrySet()) {
            Id childId = entry.getKey();
            Id parentId = entry.getValue();

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String directedKey = String.valueOf(childId) + '|' + String.valueOf(parentId);

            if (childByDirectedKey.containsKey(directedKey)) {
                continue;
            }

            childByDirectedKey.put(directedKey, childId);
            parentByDirectedKey.put(directedKey, parentId);

            String unorderedKey = unorderedKey(childId, parentId);

            if (!directedKeysByUnorderedPair.containsKey(unorderedKey)) {
                directedKeysByUnorderedPair.put(unorderedKey, new List<String>());
            }

            directedKeysByUnorderedPair.get(unorderedKey).add(directedKey);
        }

        if (childByDirectedKey.isEmpty()) {
            return;
        }

        Set<String> selectedDirectedKeys = new Set<String>();

        for (String unorderedKey : directedKeysByUnorderedPair.keySet()) {
            List<String> directedKeys = directedKeysByUnorderedPair.get(unorderedKey);
            String selectedKey = directedKeys.get(0);

            for (String directedKey : directedKeys) {
                if (directedKey < selectedKey) {
                    selectedKey = directedKey;
                }
            }

            selectedDirectedKeys.add(selectedKey);
        }

        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (String directedKey : selectedDirectedKeys) {
            childIds.add(childByDirectedKey.get(directedKey));
            parentIds.add(parentByDirectedKey.get(directedKey));
        }

        Set<String> existingUnorderedPairs = new Set<String>();

        List<npe4__Relationship__c> existingRelationships = [
            SELECT Id, npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WITH SECURITY_ENFORCED
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
            OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ];

        for (npe4__Relationship__c relationship : existingRelationships) {
            if (relationship.npe4__Contact__c == null || relationship.npe4__RelatedContact__c == null) {
                continue;
            }

            existingUnorderedPairs.add(
                unorderedKey(relationship.npe4__Contact__c, relationship.npe4__RelatedContact__c)
            );
        }

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (String directedKey : selectedDirectedKeys) {
            Id childId = childByDirectedKey.get(directedKey);
            Id parentId = parentByDirectedKey.get(directedKey);
            String unorderedKey = unorderedKey(childId, parentId);

            if (existingUnorderedPairs.contains(unorderedKey)) {
                continue;
            }

            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    private static String unorderedKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        return first < second ? first + '|' + second : second + '|' + first;
    }
}
