public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        Set<Id> idsToQuery = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null && normalizeId(recordId) != null) {
                idsToQuery.add(recordId);
            }
        }

        if (idsToQuery.isEmpty()) {
            return editableRecordIds;
        }

        Set<String> editableNormalizedIds = new Set<String>();
        List<Id> queryIds = new List<Id>(idsToQuery);

        for (UserRecordAccess userRecordAccess : [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :UserInfo.getUserId()
              AND RecordId IN :queryIds
        ]) {
            if (userRecordAccess.HasEditAccess) {
                String normalizedRecordId = normalizeId(userRecordAccess.RecordId);
                if (normalizedRecordId != null) {
                    editableNormalizedIds.add(normalizedRecordId);
                }
            }
        }

        for (Id recordId : recordIds) {
            String normalizedId = normalizeId(recordId);
            if (normalizedId != null && editableNormalizedIds.contains(normalizedId)) {
                editableRecordIds.add(recordId);
            }
        }

        return editableRecordIds;
    }

    private static String normalizeId(Id id) {
        if (id == null) {
            return null;
        }

        String idValue = String.valueOf(id);
        if (idValue.length() != 15 && idValue.length() != 18) {
            return null;
        }

        return idValue.left(15);
    }
}
