public class TA_Case_AddClosureComment implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldCaseMap = new Map<Id, Case>();
        for (SObject sObject : triggerOld) {
            Case oldCase = (Case) sObject;
            oldCaseMap.put(oldCase.Id, oldCase);
        }

        List<CaseComment> closureComments = new List<CaseComment>();
        String closureDate = String.valueOf(Date.today());

        for (SObject sObject : triggerNew) {
            Case currentCase = (Case) sObject;
            Case oldCase = oldCaseMap.get(currentCase.Id);
            if (currentCase.Status == 'Closed' && oldCase != null && oldCase.Status != 'Closed') {
                closureComments.add(new CaseComment(
                    ParentId = currentCase.Id,
                    CommentBody = 'Case closed on ' + closureDate,
                    IsPublished = false
                ));
            }
        }

        if (!closureComments.isEmpty()) {
            insert closureComments;
        }
    }
}
